// Revenue conversion fix: ensure paidEvents increments on successful checkout
// This module hooks into the checkout completion flow and triggers revenue recording

const revenueModule = require('./revenue-module');

async function onCheckoutComplete(order) {
  if (!order || !order.total || order.total <= 0) return;
  try {
    await revenueModule.recordPayment({
      amount: order.total,
      currency: order.currency || 'USD',
      orderId: order.id,
      customerId: order.customerId,
      timestamp: new Date().toISOString()
    });
    console.log(`Revenue recorded for order ${order.id}: ${order.total}`);
  } catch (err) {
    console.error('Revenue recording failed:', err);
  }
}

module.exports = { onCheckoutComplete };
